/*
 * Target: -mt9000tvx
 * test_tvx_vec.c - on-target check for the TVX vector inference kernels
 * (VSETLEN, VADDSN, VMULSN, VSILUSN, VRMSNORM, VSOFTMAXSN, MXFP4GEMVBF).
 *
 * Expected values in tvx_vec_vectors.inc are generated by tvx_genvec_vec.c
 * from the double-precision definition in the spec, so this checks the
 * instructions against the specification, not against themselves.
 *
 * Also checks that MXFP4GEMVBF equals MXFP4GEMV fed the same values through
 * float32, and that VSETLEN bounds the write (nothing past the length).
 *
 * Build & run: see transputer/TVX-ISA.md section 6.
 */

#include "tvx_vec_vectors.inc"
#define UART_DATA (*(volatile unsigned int *)0x10000000)
static void up(int c){UART_DATA=(unsigned)(unsigned char)c;}
static void us(const char*s){while(*s)up(*s++);}
static void uh(unsigned v){int i;for(i=28;i>=0;i-=4){int n=(v>>i)&0xF;up(n<10?'0'+n:'a'+n-10);}}
static void ud(unsigned v){char b[12];int n=0;if(!v){up('0');return;}while(v){b[n++]='0'+v%10;v/=10;}while(n)up(b[--n]);}
static unsigned f2b(float f){union{float f;unsigned u;}v;v.f=f;return v.u;}
static float b2f(unsigned u){union{float f;unsigned u;}v;v.u=u;return v.f;}
static int bad=0, ck=0;
static void eq(const char*w,int i,unsigned g,unsigned e){ck++;if(g!=e){bad++;us("\nFAIL ");us(w);us("[");ud((unsigned)i);us("] got=");uh(g);us(" want=");uh(e);}}
static float X[VN], G[VN], Y[VN], O[VN];
/* MXFP4 weights + bf16 activations for the GEMVBF check */
static unsigned char W[2*17];
static float actf[64];
static unsigned short actb[64];
int test_main(void){
    int i; float r1, r2;
    for(i=0;i<VN;i++){ X[i]=b2f(vx[i]); G[i]=b2f(vg[i]); Y[i]=b2f(vy[i]); }
    __vsetlen(VN);

    __vadd(O, X, Y);      for(i=0;i<VN;i++) eq("vadd", i, f2b(O[i]), e_add[i]);
    __vmul(O, X, Y);      for(i=0;i<VN;i++) eq("vmul", i, f2b(O[i]), e_mul[i]);
    __vsilu(O, X);        for(i=0;i<VN;i++) eq("vsilu", i, f2b(O[i]), e_silu[i]);
    __vrmsnorm(O, X, G);  for(i=0;i<VN;i++) eq("vrms", i, f2b(O[i]), e_rms[i]);
    __vsoftmax(O, X);     for(i=0;i<VN;i++) eq("vsoftmax", i, f2b(O[i]), e_sm[i]);

    /* MXFP4GEMVBF must equal MXFP4GEMV fed the same values via f32 */
    for(i=0;i<2*17;i++) W[i]=(unsigned char)(0x29+i*11);
    W[0]=127; W[17]=128;
    for(i=0;i<64;i++){
        actb[i] = (unsigned short)__f32tobf16(f2b((float)((i%11)-5)*0.25f));
        actf[i] = b2f(__bf16tof32(actb[i]));   /* exactly what the bf16 lane holds */
    }
    r1 = __mxfp4gemv(W, actf, 2, 0.75f);
    r2 = __mxfp4gemvbf(W, actb, 2, 0.75f);
    eq("gemvbf", 0, f2b(r2), f2b(r1));

    /* vsetlen must be re-settable */
    __vsetlen(4);
    for(i=0;i<VN;i++) O[i]=0.0f;
    __vadd(O, X, Y);
    for(i=0;i<4;i++)  eq("len4.in", i, f2b(O[i]), e_add[i]);
    for(i=4;i<VN;i++) eq("len4.out", i, f2b(O[i]), 0u);

    us("\nchecks="); ud((unsigned)ck); us(" failures="); ud((unsigned)bad);
    us(bad?"\nVEC: FAIL\n":"\nVEC: PASS\n");
    return bad;
}
